mapper.select:
select  from mall_member_coupon mc
join mall_coupon_template t on t.coupon_id=mc.coupon_id
where mc.member_coupon_id=#{memberCouponId} and mc.member_id=#{memberId}

select  from mall_member_coupon mc
join mall_coupon_template t on t.coupon_id=mc.coupon_id where mc.member_id=#{memberId}
order by case mc.status when 'AVAILABLE' then 1 when 'LOCKED' then 2 else 3 end,t.valid_to,mc.member_coupon_id desc

select distinct s.sku_id from mall_sku s join mall_spu p on p.spu_id=s.spu_id
where s.sku_id in
#{skuId}
and exists(select 1 from mall_coupon_scope cs where cs.coupon_id=#{couponId}
    and cs.target_id=p.category_id
    and cs.target_id=p.spu_id)
